	[[nodiscard]] inline const DominationMap* findDominationMap(std::uint32_t map)
	{
		const auto found = std::ranges::find(dominationMaps, map, &DominationMap::map);
		return found != dominationMaps.end() ? &*found : nullptr;
	}
